out = []
seen = set()
for k, v in T.items():
    for x in v.replace('\n', '|').split('|'):
        x = x.strip()
        i = x.rfind(' ')
        en, zh = x[:i].strip(), x[i + 1:].strip()
        assert en and zh and (' ' in en or '-' in en), x
        if en.lower() in seen:
            continue
        seen.add(en.lower())
        out.append([en, zh])
json.dump(out, open(Path(__file__).resolve().parent.parent / 'r37_src/wordbank_phrase.json', 'w'), ensure_ascii=False, separators=(',', ':'))
print(len(out), 'phrases')
